:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --ink: #15171a;
  --ink-soft: #44474d;
  --ink-muted: #6b6f76;
  --line: #e4e4df;
  --line-strong: #c9c9c2;
  --accent: #1a3a2e;
  --accent-ink: #ffffff;
  --accent-hover: #0f261d;
  --highlight: #f4ede1;
  --sale: #b4321b;
  --sale-bg: #fbeae6;
  --focus: #1a3a2e;
  --shadow-sm: 0 1px 2px rgba(20, 22, 26, 0.06);
  --shadow-md: 0 8px 24px rgba(20, 22, 26, 0.08);
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --container: 1240px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;
  --space-9: 96px;
  --font-display: "Fraunces", "Times New Roman", Georgia, serif;
  --font-body: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { display: block; max-width: 100%; height: auto; }

a { color: inherit; text-decoration: none; }

button { font: inherit; color: inherit; cursor: pointer; }

h1, h2, h3, h4 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.15;
}

p { margin: 0; }

/* Focus styles - visible on all interactive elements */
:focus { outline: none; }
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100px;
  left: var(--space-4);
  background: var(--ink);
  color: var(--bg);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-sm);
  z-index: 1000;
  font-weight: 600;
}
.skip-link:focus { top: var(--space-4); }

.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--space-5);
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ───────── Announcement bar ───────── */
.announcement {
  background: var(--ink);
  color: #f7f5f0;
  font-size: 13px;
  text-align: center;
  padding: 10px var(--space-4);
  letter-spacing: 0.02em;
}
.announcement strong { font-weight: 600; }

/* ───────── Header ───────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(160%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 72px;
  gap: var(--space-5);
}
.brand {
  font-family: var(--font-display);
  font-size: 24px;
  letter-spacing: 0.01em;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.brand-mark {
  width: 28px; height: 28px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 50%;
  display: inline-grid;
  place-items: center;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 13px;
}

.primary-nav {
  display: flex;
  justify-content: center;
}
.primary-nav ul {
  display: flex;
  gap: var(--space-6);
  list-style: none;
  margin: 0; padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 2px;
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-soft);
  border-bottom: 2px solid transparent;
  transition: color .15s, border-color .15s;
}
.primary-nav a:hover { color: var(--ink); border-bottom-color: var(--ink); }

.header-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: var(--space-2);
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  width: 40px; height: 40px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  color: var(--ink);
  position: relative;
  transition: background .15s, border-color .15s;
}
.icon-btn:hover { background: rgba(20,22,26,0.06); }
.icon-btn svg { width: 20px; height: 20px; stroke: currentColor; fill: none; stroke-width: 1.6; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  background: var(--sale);
  color: #fff;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  line-height: 1;
  border: 2px solid var(--bg);
}

.menu-toggle { display: none; }

/* ───────── Hero ───────── */
.hero {
  padding: var(--space-7) 0 var(--space-8);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: var(--space-7);
  align-items: center;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--accent);
  background: var(--highlight);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: var(--space-5);
}
.hero h1 {
  font-size: clamp(40px, 6vw, 72px);
  letter-spacing: -0.02em;
  margin-bottom: var(--space-5);
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
}
.hero-lede {
  font-size: 18px;
  color: var(--ink-soft);
  max-width: 52ch;
  margin-bottom: var(--space-6);
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.01em;
  border: 1px solid transparent;
  transition: transform .12s, background .15s, color .15s, border-color .15s;
  text-decoration: none;
  background: transparent;
}
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: var(--accent-hover); }
.btn-secondary { background: transparent; color: var(--ink); border-color: var(--line-strong); }
.btn-secondary:hover { border-color: var(--ink); background: var(--surface); }
.btn-link {
  padding: 0;
  background: transparent;
  border: none;
  color: var(--ink);
  font-weight: 600;
  font-size: 14px;
  border-bottom: 1px solid currentColor;
  border-radius: 0;
  padding-bottom: 2px;
}
.btn:active { transform: translateY(1px); }
.btn svg { width: 16px; height: 16px; }

.hero-meta {
  display: flex;
  gap: var(--space-6);
  flex-wrap: wrap;
  padding-top: var(--space-5);
  border-top: 1px solid var(--line);
}
.hero-meta div { font-size: 13px; color: var(--ink-muted); }
.hero-meta strong {
  display: block;
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 500;
  margin-bottom: 2px;
}

.hero-visual {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, #e8e3d6 0%, #d6cdb6 100%);
  box-shadow: var(--shadow-md);
}
.hero-visual::after {
  /* decorative shape */
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 30%, rgba(255,255,255,.5), transparent 50%),
    radial-gradient(circle at 75% 75%, rgba(26,58,46,.18), transparent 60%);
}
.hero-visual-inner {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: clamp(60px, 12vw, 140px);
  color: rgba(26,58,46,.18);
  font-style: italic;
}
.hero-badge {
  position: absolute;
  bottom: var(--space-5);
  left: var(--space-5);
  background: var(--surface);
  border-radius: var(--radius-md);
  padding: var(--space-3) var(--space-4);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  gap: var(--space-3);
  z-index: 2;
}
.hero-badge-icon {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--highlight);
  display: grid; place-items: center;
  color: var(--accent);
}
.hero-badge-text { font-size: 13px; }
.hero-badge-text strong { display: block; font-weight: 600; }
.hero-badge-text span { color: var(--ink-muted); }

/* ───────── Section heading ───────── */
.section { padding: var(--space-8) 0; }
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: var(--space-5);
  margin-bottom: var(--space-6);
  flex-wrap: wrap;
}
.section-head h2 {
  font-size: clamp(28px, 3.5vw, 40px);
}
.section-head p { color: var(--ink-muted); margin-top: 8px; max-width: 50ch; }
.section-eyebrow {
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: var(--space-3);
}

/* ───────── Categories ───────── */
.categories {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}
.category-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-5);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  text-align: left;
  transition: border-color .15s, transform .15s;
  position: relative;
}
.category-card:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
}
.category-thumb {
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 36px;
  color: var(--accent);
}
.category-card h3 {
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.category-card .arrow {
  display: inline-grid; place-items: center;
  width: 28px; height: 28px;
  border-radius: 50%;
  border: 1px solid var(--line-strong);
  transition: background .15s, color .15s, border-color .15s;
}
.category-card:hover .arrow { background: var(--ink); color: var(--bg); border-color: var(--ink); }
.category-card span.count { color: var(--ink-muted); font-size: 13px; }

/* ───────── Products ───────── */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-5);
}
.product-card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: border-color .15s, transform .15s, box-shadow .15s;
}
.product-card:hover {
  border-color: var(--line-strong);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 48px;
  color: rgba(20,22,26,0.18);
  font-style: italic;
}
.product-tag {
  position: absolute;
  top: var(--space-3); left: var(--space-3);
  background: var(--surface);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  color: var(--ink);
}
.product-tag.sale { background: var(--sale); color: #fff; }
.product-tag.new { background: var(--accent); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: var(--space-3); right: var(--space-3);
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--surface);
  border: 1px solid var(--line);
  display: grid; place-items: center;
  color: var(--ink-soft);
  transition: color .15s, background .15s;
}
.wishlist-btn svg { width: 18px; height: 18px; stroke: currentColor; fill: none; stroke-width: 1.6; }
.wishlist-btn[aria-pressed="true"] { color: var(--sale); }
.wishlist-btn[aria-pressed="true"] svg { fill: var(--sale); }
.wishlist-btn:hover { background: var(--bg); }

.product-body {
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  flex: 1;
}
.product-category {
  font-size: 12px;
  color: var(--ink-muted);
  letter-spacing: 0.04em;
}
.product-name {
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--ink-soft);
}
.product-rating .stars { color: #d4a017; letter-spacing: 1px; }
.product-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  padding-top: var(--space-3);
}
.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.price-current { font-weight: 700; font-size: 16px; color: var(--ink); }
.price-original {
  font-size: 13px;
  color: var(--ink-muted);
  text-decoration: line-through;
}
.add-btn {
  display: inline-grid;
  place-items: center;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--ink);
  color: var(--bg);
  border: none;
  transition: background .15s, transform .15s;
}
.add-btn:hover { background: var(--accent); }
.add-btn svg { width: 16px; height: 16px; stroke: currentColor; fill: none; stroke-width: 2; }

/* ───────── Deals strip ───────── */
.deals {
  background: linear-gradient(135deg, #1a3a2e 0%, #244c3d 100%);
  color: #f4ede1;
  border-radius: var(--radius-lg);
  padding: var(--space-7);
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: var(--space-7);
  margin: 0 var(--space-5);
}
.deals-inner { padding: 0; }
.deals-content h2 { color: #fff; font-size: clamp(28px, 3.5vw, 40px); margin-bottom: var(--space-3); }
.deals-content p { color: rgba(244,237,225,0.8); margin-bottom: var(--space-5); max-width: 50ch; }

.countdown {
  display: flex;
  gap: var(--space-3);
  margin-bottom: var(--space-5);
}
.countdown-unit {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius-sm);
  padding: 12px 18px;
  text-align: center;
  min-width: 72px;
}
.countdown-num {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 500;
  display: block;
  line-height: 1;
  color: #fff;
  font-variant-numeric: tabular-nums;
}
.countdown-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(244,237,225,0.7);
  margin-top: 6px;
  display: block;
}
.deals .btn-primary { background: var(--highlight); color: var(--accent); }
.deals .btn-primary:hover { background: #fff; }

.deals-visual {
  width: 280px;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  background:
    radial-gradient(circle at 30% 30%, rgba(244,237,225,0.25), transparent 60%),
    rgba(255,255,255,0.06);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-style: italic;
  font-size: 96px;
  color: rgba(244,237,225,0.35);
  border: 1px solid rgba(255,255,255,0.12);
}

/* ───────── Editorial ───────── */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: var(--space-5);
}
.editorial-card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform .15s, box-shadow .15s;
}
.editorial-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.editorial-card.feature {
  grid-row: span 2;
  background: var(--surface);
}
.editorial-media {
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #e8e3d6, #c9c0a8);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-style: italic;
  font-size: 48px;
  color: rgba(26,58,46,0.25);
}
.editorial-card.feature .editorial-media {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #d8cfb8, #a89a7a);
}
.editorial-body {
  padding: var(--space-5);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  flex: 1;
}
.editorial-card.feature .editorial-body { padding: var(--space-6); }
.editorial-meta {
  display: flex;
  gap: var(--space-3);
  font-size: 12px;
  color: var(--ink-muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.editorial-tag {
  color: var(--accent);
  font-weight: 700;
}
.editorial-card h3 {
  font-size: 22px;
}
.editorial-card.feature h3 {
  font-size: clamp(28px, 3vw, 36px);
}
.editorial-card p {
  color: var(--ink-soft);
  font-size: 15px;
}
.editorial-card .read-more {
