}
.editorial-card:hover .read-more::after { transform: translateX(4px); }

/* ───────── Newsletter ───────── */
.newsletter {
  background: var(--highlight);
  border-radius: var(--radius-lg);
  padding: var(--space-7);
  text-align: center;
  margin: 0 var(--space-5);
}
.newsletter-content { max-width: 560px; margin: 0 auto; }
.newsletter h2 { font-size: clamp(28px, 3vw, 36px); margin-bottom: var(--space-3); }
.newsletter p { color: var(--ink-soft); margin-bottom: var(--space-5); }
.newsletter-form {
  display: flex;
  gap: var(--space-3);
  flex-wrap: wrap;
  justify-content: center;
}
.newsletter-field {
