  font-size: 14px;
  font-weight: 500;
  color: var(--accent);
}

.newsletter-fineprint {
  margin-top: var(--space-4);
  font-size: 12px;
  color: var(--ink-muted);
}

/* ───────── Footer ───────── */
.site-footer {
