}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { font-size: 14px; color: rgba(255,255,255,0.65); }
.footer-col a:hover { color: #fff; }

.footer-bottom {
  margin-top: var(--space-5);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-3);
  font-size: 13px;
  color: rgba(255,255,255,0.5);
}
.footer-bottom .socials { display: flex; gap: var(--space-2); }
.footer-bottom .socials a {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.15);
  color: rgba(255,255,255,0.7);
  transition: background .15s, color .15s, border-color .15s;
}
.footer-bottom .socials a:hover { background: #fff; color: var(--ink); border-color: #fff; }
.footer-bottom .socials svg { width: 16px; height: 16px; fill: currentColor; }

/* ───────── Reduced motion ───────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ───────── Forced colors ───────── */
@media (forced-colors: active) {
  .btn, .icon-btn, .add-btn, .category-card, .product-card, .editorial-card, .newsletter-input {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .add-btn { background: ButtonText; color: ButtonFace; }
  :focus-visible { outline: 2px solid Highlight; }
}

/* ───────── Responsive ───────── */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .categories { grid-template-columns: repeat(4, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.feature { grid-column: span 2; grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: span 3; }
  .deals { grid-template-columns: 1fr; padding: var(--space-6); }
  .deals-visual { width: 100%; max-width: 320px; margin: 0 auto; }
}

@media (max-width: 768px) {
  .hero-grid { grid-template-columns: 1fr; gap: var(--space-6); }
  .hero-visual { aspect-ratio: 4/3; max-height: 460px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .categories { grid-template-columns: repeat(2, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.feature { grid-column: auto; }
  .header-inner { grid-template-columns: auto 1fr auto; height: 64px; }
  .primary-nav {
    display: none;
    position: absolute;
    top: 100%; left: 0; right: 0;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: var(--space-4) var(--space-5);
  }
  .primary-nav[data-open="true"] { display: block; }
  .primary-nav ul { flex-direction: column; gap: var(--space-3); }
  .menu-toggle { display: inline-grid; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
}

@media (max-width: 480px) {
  .product-grid { grid-template-columns: 1fr 1fr; gap: var(--space-3); }
  .product-body { padding: var(--space-3); }
  .product-name { font-size: 14px; }
  .countdown-unit { padding: 10px 12px; min-width: 60px; }
  .countdown-num { font-size: 26px; }
  .deals, .newsletter { margin: 0; border-radius: var(--radius-md); padding: var(--space-5); }
  .container { padding: 0 var(--space-4); }
}

