      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
      setError("Please enter a valid email address (for example, name@example.com).");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setStatus(`Thanks — we've sent a welcome note to ${email.trim()}.`);
    setEmail("");
  };

  return h("section", { className: "section", "aria-labelledby": "nl-title", id: "newsletter", style: { padding: "32px 0 64px" } },
    h("div", { className: "newsletter" },
      h("div", { className: "newsletter-content" },
        h("p", { className: "section-eyebrow" }, "Stay in touch"),
        h("h2", { id: "nl-title" }, "Letters from the Maison"),
