              value: email,
              onChange: e => { setEmail(e.target.value); if (error) setError(""); },
              "aria-invalid": error ? "true" : "false",
              "aria-describedby": "newsletter-error newsletter-hint"
            }),
            h("span", { id: "newsletter-error", className: "newsletter-error", role: error ? "alert" : undefined },
              error || ""
            )
          ),
          h("button", { type: "submit", className: "btn btn-primary newsletter-submit" }, "Subscribe")
        ),
        h("p", { id: "newsletter-status", className: "newsletter-status", role: "status", "aria-live": "polite" }, status),
        h("p", { id: "newsletter-hint", className: "newsletter-fineprint" },
