function Footer() {
  const cols = [
    { title: "Shop", links: ["New Arrivals", "Best Sellers", "Outerwear", "Knitwear", "Sale"] },
    { title: "Company", links: ["Our Story", "Sustainability", "Ateliers", "Press", "Careers"] },
