/* Maison Verte — minimal React-style runtime + components */
const { useState, useEffect, useRef, useCallback, useMemo } = React;
const h = React.createElement;

/* ───────── Icons ───────── */
const Icon = ({ name, ...props }) => {
  const paths = {
    search: "M11 4a7 7 0 1 1 0 14 7 7 0 0 1 0-14zm9 16-3.5-3.5",
    user: "M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm-7 9a7 7 0 0 1 14 0",
    bag: "M6 8h12l-1 12H7L6 8zm3 0a3 3 0 1 1 6 0",
    heart: "M12 20s-7-4.5-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.5-7 10-7 10z",
    plus: "M12 5v14M5 12h14",
    arrow: "M5 12h14M13 6l6 6-6 6",
    menu: "M4 7h16M4 12h16M4 17h16",
    close: "M6 6l12 12M18 6 6 18",
    truck: "M3 7h11v8H3zM14 10h4l3 3v2h-7zM7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4zm10 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4z",
    leaf: "M5 19c0-8 6-14 14-14 0 8-6 14-14 14zM5 19l8-8",
  };
  return h("svg", { viewBox: "0 0 24 24", "aria-hidden": "true", ...props },
    h("path", { d: paths[name], fill: "none", stroke: "currentColor", strokeWidth: 1.6, strokeLinecap: "round", strokeLinejoin: "round" })
  );
};

/* ───────── Data ───────── */
const NAV = [
  { label: "New Arrivals", href: "#new" },
  { label: "Shop", href: "#shop" },
  { label: "Collections", href: "#collections" },
  { label: "Editorial", href: "#editorial" },
  { label: "About", href: "#about" },
];

const CATEGORIES = [
  { name: "Outerwear", count: 84, glyph: "Ow", bg: "linear-gradient(135deg,#e3dfd0,#c9c2a8)" },
  { name: "Knitwear", count: 56, glyph: "Kn", bg: "linear-gradient(135deg,#efe3d1,#d8c4a3)" },
  { name: "Footwear", count: 42, glyph: "Fw", bg: "linear-gradient(135deg,#dad4c1,#b3a986)" },
  { name: "Accessories", count: 128, glyph: "Ac", bg: "linear-gradient(135deg,#e8e1cd,#c5b893)" },
