  { id: 3, name: "Linen Wide-Leg Trouser", category: "Bottoms", price: 145, rating: 4.6, reviews: 52, glyph: "Tr", bg: "linear-gradient(135deg,#e8e2d0,#c1b690)" },
  { id: 4, name: "Suede Loafers — Tan", category: "Footwear", price: 240, original: 290, rating: 4.7, reviews: 211, tag: "sale", glyph: "Lf", bg: "linear-gradient(135deg,#d6cdb1,#a89a73)" },
  { id: 5, name: "Silk Blend Scarf", category: "Accessories", price: 95, rating: 4.5, reviews: 38, glyph: "Sc", bg: "linear-gradient(135deg,#efe9d8,#d4c89f)" },
  { id: 6, name: "Organic Cotton Shirt", category: "Tops", price: 110, rating: 4.4, reviews: 76, tag: "new", glyph: "Sh", bg: "linear-gradient(135deg,#e3ddc8,#bfb38c)" },
  { id: 7, name: "Leather Crossbody Bag", category: "Accessories", price: 295, rating: 4.9, reviews: 153, glyph: "Bg", bg: "linear-gradient(135deg,#d2c8ad,#a09271)" },
