  { id: "e1", category: "Lookbook", date: "Spring '26", title: "The Garden Capsule: a study in restraint", excerpt: "Eight pieces, infinite combinations. Our spring drop revisits the wardrobe through a lens of quiet utility.", feature: true, glyph: "Ed", bg: "linear-gradient(135deg,#d8cfb8,#9f9170)" },
  { id: "e2", category: "Craft", date: "5 min read", title: "Inside our Tuscan wool atelier", excerpt: "How three generations of weavers shape every overcoat.", glyph: "At", bg: "linear-gradient(135deg,#e8e3d6,#bfb494)" },
