          cartCount > 0 && h("span", { className: "cart-count", "aria-hidden": "true" }, cartCount)
        )
      )
    )
  );
}

function Hero({ onShop }) {
  return h("section", { className: "hero", "aria-labelledby": "hero-title" },
    h("div", { className: "container hero-grid" },
      h("div", null,
        h("span", { className: "hero-eyebrow" },
          h("span", { "aria-hidden": "true" }, "✦"), "Spring Collection 2026"
        ),
        h("h1", { id: "hero-title" }, "Considered pieces, ", h("em", null, "made to last"), ".")
        ,
        h("p", { className: "hero-lede" },
          "A small-batch wardrobe of natural fibres, sustainable craft, and timeless silhouettes — designed in Copenhagen, woven in Tuscany."
        ),
        h("div", { className: "hero-cta" },
          h("button", { className: "btn btn-primary", onClick: onShop },
            "Shop the collection ", h(Icon, { name: "arrow" })
          ),
          h("a", { className: "btn btn-secondary", href: "#editorial" }, "Read our journal")
        ),
        h("div", { className: "hero-meta" },
          h("div", null, h("strong", null, "12k+"), "Five-star reviews"),
          h("div", null, h("strong", null, "100%"), "Natural fibres"),
          h("div", null, h("strong", null, "Free"), "Returns within 30 days")
        )
      ),
      h("div", { className: "hero-visual", "aria-hidden": "true" },
        h("div", { className: "hero-visual-inner" }, "MV"),
