function Countdown({ deadline }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, deadline - now);
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  const seconds = Math.floor((diff % 60000) / 1000);
  const pad = n => String(n).padStart(2, "0");
  return h("div", { className: "countdown", role: "timer", "aria-live": "off",
    "aria-label": `Sale ends in ${days} days, ${hours} hours, ${minutes} minutes, ${seconds} seconds` },
    [
      ["Days", days], ["Hours", hours], ["Minutes", minutes], ["Seconds", seconds]
    ].map(([label, val]) => h("div", { className: "countdown-unit", key: label, "aria-hidden": "true" },
      h("span", { className: "countdown-num" }, pad(val)),
      h("span", { className: "countdown-label" }, label)
    ))
  );
}

