function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const handleSubmit = e => {
    e.preventDefault();
    setStatus("");
    if (!email.trim()) {
      setError("Please enter your email address.");
      inputRef.current?.focus();
      return;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
      setError("Please enter a valid email address (for example, name@example.com).");
      inputRef.current?.focus();
      return;
    }
    setError("");
    setStatus(`Thanks — we've sent a welcome note to ${email.trim()}.`);
    setEmail("");
  };

  return h("section", { className: "section", "aria-labelledby": "nl-title", id: "newsletter", style: { padding: "32px 0 64px" } },
    h("div", { className: "newsletter" },
      h("div", { className: "newsletter-content" },
        h("p", { className: "section-eyebrow" }, "Stay in touch"),
        h("h2", { id: "nl-title" }, "Letters from the Maison"),
        h("p", null, "Early access to new drops, atelier stories, and a 10% welcome offer. No spam, ever."),
        h("form", { className: "newsletter-form", onSubmit: handleSubmit, noValidate: true },
          h("div", { className: "newsletter-field" },
            h("label", { htmlFor: "newsletter-email" },
              "Email address ", h("span", { className: "required", "aria-hidden": "true" }, "*")
            ),
            h("input", {
              id: "newsletter-email",
              ref: inputRef,
              className: "newsletter-input",
              type: "email",
              required: true,
              "aria-required": "true",
              autoComplete: "email",
              placeholder: "you@example.com",
              value: email,
              onChange: e => { setEmail(e.target.value); if (error) setError(""); },
              "aria-invalid": error ? "true" : "false",
              "aria-describedby": "newsletter-error newsletter-hint"
            }),
            h("span", { id: "newsletter-error", className: "newsletter-error", role: error ? "alert" : undefined },
              error || ""
            )
          ),
          h("button", { type: "submit", className: "btn btn-primary newsletter-submit" }, "Subscribe")
        ),
        h("p", { id: "newsletter-status", className: "newsletter-status", role: "status", "aria-live": "polite" }, status),
        h("p", { id: "newsletter-hint", className: "newsletter-fineprint" },
          "By subscribing you agree to our ", h("a", { href: "#privacy", style: { textDecoration: "underline" } }, "privacy policy"), ". Required field marked with *."
        )
      )
    )
  );
}

