/* ───────── App ───────── */
function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [toast, setToast] = useState("");

  const addToCart = useCallback(p => {
    setCart(c => [...c, p.id]);
    setToast(`${p.name} added to your bag`);
  }, []);

  const toggleWishlist = useCallback(id => {
    setWishlist(w => {
      const next = new Set(w);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }, []);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 2500);
    return () => clearTimeout(t);
  }, [toast]);

  const scrollToShop = () => document.getElementById("new")?.scrollIntoView({ behavior: "smooth" });

  return h(React.Fragment, null,
    h("a", { className: "skip-link", href: "#main" }, "Skip to main content"),
    h(Announcement),
    h(Header, { cartCount: cart.length }),
    h("main", { id: "main" },
      h(Hero, { onShop: scrollToShop }),
      h(Categories),
      h(FeaturedProducts, { onAdd: addToCart, wishlist, onToggleWishlist: toggleWishlist }),
      h(Deals),
      h(Editorial),
      h(Newsletter)
    ),
    h(Footer),
    h("div", {
      role: "status",
      "aria-live": "polite",
      style: {
        position: "fixed",
        bottom: toast ? 24 : -100,
        left: "50%",
        transform: "translateX(-50%)",
        background: "#15171a",
        color: "#fff",
        padding: "12px 20px",
        borderRadius: 999,
        fontSize: 14,
        fontWeight: 500,
        boxShadow: "0 8px 24px rgba(0,0,0,0.2)",
        transition: "bottom .3s ease",
        zIndex: 100,
        pointerEvents: "none"
      }
    }, toast)
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(h(App));
